INSERT INTO products (name, category, description, price_range, unit, specs, sort_order) VALUES
('莎安娜米黄大理石', '大理石', '伊朗进口，底色温润如玉，纹理细腻均匀，适合高档室内墙面、地面装饰，光泽度极佳。', '380-580元', '平方米', '{"产地": "伊朗", "密度": "2.7g/cm³", "吸水率": "0.15%", "抗压强度": "120MPa", "光泽度": "90+"}', 1),
('黑白根大理石', '大理石', '黑色底色配白色纹理，对比强烈，现代感十足。适用于地面、台面、背景墙，性价比高。', '180-280元', '平方米', '{"产地": "中国广西", "密度": "2.68g/cm³", "吸水率": "0.2%", "抗压强度": "100MPa"}', 2),
('爵士白大理石', '大理石', '白色基底，灰色纹理如山水画般自然流畅。经典的高端装饰材料，适用于酒店、别墅。', '420-650元', '平方米', '{"产地": "希腊", "密度": "2.65g/cm³", "吸水率": "0.18%", "抗压强度": "110MPa"}', 3),
('金碧辉煌大理石', '大理石', '金黄色底色配深色纹理，华贵大气。常用于酒店大堂、豪宅客厅等高端场所。', '350-500元', '平方米', '{"产地": "中国湖北", "密度": "2.7g/cm³", "吸水率": "0.2%", "光泽度": "85+"}', 4),
('皇室啡花岗岩', '花岗岩', '深棕色底色带黑色斑点，硬度极高，耐磨损。适合室外广场、台阶、外墙干挂。', '150-250元', '平方米', '{"产地": "印度", "密度": "2.8g/cm³", "吸水率": "0.08%", "抗压强度": "200MPa", "莫氏硬度": "6.5"}', 5),
('芝麻灰花岗岩', '花岗岩', '灰色调，颗粒均匀细腻。性价比最高的室外石材之一，广泛用于市政工程、园林景观。', '80-150元', '平方米', '{"产地": "中国福建", "密度": "2.75g/cm³", "吸水率": "0.1%", "抗压强度": "180MPa"}', 6),
('蓝钻石英石', '人造石', '蓝色晶体点缀，硬度高，不渗色不吸油。台面首选材料，食品级安全。', '280-420元', '平方米', '{"产地": "中国广东", "密度": "2.4g/cm³", "吸水率": "0.02%", "莫氏硬度": "7", "厚度": "15mm/20mm"}', 7),
('卡拉拉白石英石', '人造石', '纯白底色仿天然大理石纹理，无辐射，环保健康。适合厨房台面、吧台。', '320-480元', '平方米', '{"产地": "中国广东", "密度": "2.4g/cm³", "吸水率": "0.02%", "莫氏硬度": "7"}', 8),
('黄金麻荔枝面', '花岗岩', '表面荔枝面处理，防滑性能好，金黄色调温暖自然。适用于室外地面、外墙。', '120-200元', '平方米', '{"产地": "中国山东", "表面处理": "荔枝面", "密度": "2.7g/cm³", "抗压强度": "160MPa"}', 9),
('雅士白人造岗石', '人造石', '仿雅士白大理石纹理，价格实惠，无色差，适合大面积铺贴和工程装修。', '120-200元', '平方米', '{"产地": "中国广东", "密度": "2.45g/cm³", "吸水率": "0.05%", "规格": "多种尺寸可选"}', 10);
INSERT INTO faqs (question, answer, category, priority) VALUES
('你们有哪些石材品种？', '我们有大理石、花岗岩、人造石三大类共几十个品种。大理石包括莎安娜米黄、黑白根、爵士白、金碧辉煌等；花岗岩有皇室啡、芝麻灰、黄金麻等；人造石有蓝钻石英石、卡拉拉白石英石等。您可以根据使用场景（室内/室外、墙面/地面/台面）来选择适合的品种~', '产品咨询', 10),
('大理石和人造石有什么区别？', '大理石是天然石材，纹理独一无二，质感高级，但需要定期保养，价格相对较高。人造石（石英石/岗石）硬度更高，不渗色不吸油，保养简单，价格更实惠，但纹理是人工的。如果是厨房台面建议人造石，客厅背景墙建议大理石~', '产品咨询', 9),
('石材怎么计算价格？', '石材通常按"平方米"计价，价格因品种、厚度、表面处理不同而有差异。天然大理石一般在180-650元/㎡，花岗岩80-250元/㎡，人造石120-480元/㎡。具体价格需根据您选定的品种和数量来报价，建议留下联系方式获取精确报价单~', '价格相关', 8),
('你们可以寄样品吗？', '当然可以！我们提供免费样品寄送服务（快递费到付）。您可以在线选择感兴趣的石材品种，留下联系方式，我们会尽快安排寄出样品供您确认颜色和质感。', '服务相关', 7),
('石材怎么安装？', '石材安装一般分为：1)基层处理（找平、防水）；2)排版预铺；3)粘贴/干挂；4)填缝处理；5)抛光养护。我们合作的客户可提供详细的安装指导手册，部分区域还能推荐可靠的安装师傅。大面积工程建议由专业施工队操作。', '安装售后', 6),
('石材如何保养？', '1)日常清洁用清水+中性清洁剂，避免酸性清洁剂；2)大理石建议每1-2年做一次专业结晶养护；3)及时清理液体污渍，避免渗透；4)门口放地垫减少砂砾磨损；5)花岗岩和人造石保养相对简单，定期清洁即可。', '安装售后', 5),
('你们支持定制尺寸吗？', '支持的！我们可根据您的图纸进行精准切割和异形加工，包括台面开孔、倒角、磨边等。请提供详细尺寸图纸或CAD文件，我们的工厂会根据您的要求进行定制生产。', '服务相关', 5),
('石材有哪些表面处理方式？', '常见的表面处理有：1)抛光面（光亮如镜，最常用）；2)亚光面（柔和质感）；3)荔枝面（防滑，适合室外）；4)火烧面（粗犷风格）；5)喷砂面（均匀细腻）。不同处理方式适用于不同场景和风格需求。', '产品咨询', 4),
('运费怎么算？石材怎么配送？', '运费根据距离、数量、石材重量计算。广东省内一般有专车配送，外省走物流专线。我们合作的物流公司可提供送货上门服务。大宗订单可协商包邮。具体费用请咨询客服获取报价~', '服务相关', 4),
('你们的最小起订量是多少？', '常规品种没有最小起订量，一片也发货。特殊定制或异形加工可能会有最低费用要求。工程订单量大从优，价格更实惠。欢迎随时咨询~', '服务相关', 3),
('大理石会褪色吗？', '优质大理石在正常使用和保养下不会明显褪色。但长期阳光直射可能导致部分浅色大理石轻微变黄。建议窗边位置选择深色系大理石，或做好防晒措施（贴膜、窗帘等）。', '安装售后', 3),
('石材有色差吗？', '天然大理石由于形成过程不同，同一品种也会存在一定色差，这恰恰是天然石材的魅力所在。人造石则基本无色差。我们会根据您的需求进行排版精选，尽量减少色差影响。如果是大面积铺贴，建议一次性采购同一批次产品。', '产品咨询', 3),
('你们做出口吗？', '做的！我们常年出口石材到东南亚、中东、欧美等地区，有丰富的外贸经验。可提供熏蒸木箱包装、产地证等出口所需文件。欢迎外贸公司和个人客户咨询合作~', '服务相关', 2),
('可以在线看石材实物效果吗？', '我们可以提供高清实物照片和视频，也可以视频连线看货。另外我们提供免费样品寄送服务，收到样品后您可以在实际场景中对比颜色和质感，效果最直观。', '服务相关', 2),
('石材安装后多久可以使用？', '地面石材铺贴后一般24-48小时即可正常行走。如果是使用云石胶粘贴的台面，4-6小时即可固化使用。填缝剂完全固化需要24小时。建议安装后2-3天内避免大量水接触。', '安装售后', 2),
('你们的石材有辐射吗？', '所有天然石材都含有微量放射性元素，但完全在国家安全标准范围内，不会对人体造成危害。我们销售的所有石材都有放射性检测报告。人造石（石英石/岗石）基本无辐射，如果特别在意这个问题可以选择人造石。', '产品咨询', 2),
('付款方式有哪些？', '我们支持多种付款方式：银行转账、微信支付、支付宝。散客订单一般先付款后发货；工程订单可协商预付定金+货到付款的方式。长期合作客户可申请账期。', '服务相关', 1),
('石材有质保吗？', '我们承诺所售石材均为合格产品，发货前会逐一检查。如收货时发现破损或明显质量问题，请在签收24小时内联系客服，我们负责免费更换。使用过程中出现的问题不属于质保范围，但我们可以提供养护建议。', '安装售后', 1),
('你们有没有实体展厅？', '我们总部位于广东省云浮市云城区石材工业园，设有大型石材展厅，展示上百种石材样品和装饰效果。欢迎随时预约参观！外地客户也可以视频在线看展厅。', '服务相关', 1),
('可以电话咨询吗？', '当然可以！您可以拨打我们的客服热线 400-xxx-xxxx，工作日 8:30-18:00 有专业销售顾问为您服务。您也可以在这里留下联系方式，我们会主动联系您~', '服务相关', 1);
INSERT INTO sales_scripts (title, scenario, content, category) VALUES
('首次咨询开场', '新客户问候', '您好！感谢关注云浮石材。我们专注石材行业15年，拥有大理石、花岗岩、人造石全品类产品线，支持定制加工和全国配送。不管您是家庭装修还是大型工程，我们都能提供专业的一站式石材解决方案。方便告诉我您的大概需求吗？比如用在什么场景（客厅/厨房/外墙）、风格偏好、预算范围？', '开场话术'),
('价格异议处理', '客户觉得价格高', '理解您的顾虑。石材是耐用消费品，好的石材用几十年都没问题。我们的价格包含精选A级板材+专业加工+包装物流，性价比在业内很有竞争力。而且大批量采购、长期合作都有阶梯优惠价。您主要是用在什么项目呢？我帮您推荐几个性价比更高的品种~', '价格话术'),
('大板批发话术', '批发/工程客户', '我们是云浮本地源头工厂，自有矿山和加工基地，大板批发价格比市场价低15%-30%。支持全规格大板、工程板、条板定做，月产量10万平方以上，交期有保障。方便加个微信吗？我把我们的产品目录和批发报价单发给您参考。', '批发话术'),
('装修推荐话术', '家装客户咨询', '根据您家装修风格，我推荐几个搭配方案：现代简约风可以选灰色系石材（如黑白根、芝麻灰）；轻奢风适合金色系（如金碧辉煌、莎安娜米黄）；新中式推荐深色系（如皇室啡）。地面建议用大理石显档次，厨房台面用人造石更实用。您觉得哪个方向比较感兴趣呢？', '推荐话术'),
('留资引导话术', '引导客户留联系方式', '为了给您提供更精准的报价和选材建议，方便留下您的联系方式吗？我让专业销售顾问根据您的具体需求（面积、用途、预算）做一份详细方案和报价单给您参考，这样效率更高。您的信息仅用于石材服务，不会外泄~', '留资话术');
INSERT INTO knowledge_docs (title, content, category, source) VALUES
('云浮石材产业介绍', '云浮是中国四大石材基地之一，素有"中国石都"之称，拥有400多年的石材加工历史。云浮石材市场汇集了全球1000多种石材品种，年交易额超过300亿元。云浮石材企业形成了从矿山开采、荒料贸易、大板加工到异形定制、安装施工的完整产业链。我司扎根云浮15年，依托本地产业优势，为客户提供高性价比的一站式石材采购服务。', '公司介绍', '公司官网'),
('大理石选购指南', '选购大理石主要看以下几点：1)看表面——优质大理石表面光滑细腻，无明显裂纹和色斑；2)听声音——敲击声音清脆说明质地紧密；3)滴墨水测试——背面滴墨水，扩散快说明吸水率高（质量较差）；4)看光泽度——抛光后光泽度应达到85以上。大理石适合室内墙面、地面、台面，不建议用于室外（不耐酸雨）。常见品种：莎安娜米黄、黑白根、爵士白、金碧辉煌、大花白等。', '产品知识', '行业资料'),
('花岗岩特性与用途', '花岗岩是硬度最高的天然石材之一（莫氏硬度6-7），耐磨损、耐酸碱、抗风化，是室外装饰的首选材料。花岗岩因形成过程中冷却速度不同，形成细粒、中粒、粗粒等不同晶体结构。常见品种：皇室啡（印度进口，深棕色）、芝麻灰（国产，性价比高）、黄金麻（金黄色，外墙首选）、蝴蝶蓝（稀有蓝色系）。花岗岩适用于：室外广场地面、外墙干挂、台阶、园林景观、墓碑等。', '产品知识', '行业资料'),
('石材加工工艺流程', '石材从荒料到成品需要经过以下工序：1)荒料切割——用大型砂锯/绳锯将荒料切割成大板；2)表面处理——抛光/亚光/荔枝面/火烧面等；3)桥切——按尺寸精确切割；4)异形加工——台面开孔、倒角、磨边、雕刻等；5)质检——检查尺寸、表面、颜色；6)包装——根据运输方式选择合适的包装（木箱/木托/塑料膜）。我司拥有5条全自动加工生产线，日加工能力5000平方米。', '工艺技术', '内部培训'),
('石材安装施工规范', '石材安装施工操作要点：一、基层处理：地面找平层平整度≤2mm/2m，墙面基层需做防水处理；二、排版预铺：同一区域尽量使用同一批次石材，预先排版调整色差和纹理；三、铺贴/干挂：地面用水泥砂浆（1:3），墙面分干挂和湿贴两种方式；四、填缝：使用专用填缝剂，颜色与石材协调；五、养护：铺贴后24-48小时避免上人，清洁时使用中性清洁剂，定期做结晶养护保持光泽。大型工程建议聘请专业施工队伍并购买工程保险。', '工艺技术', '施工规范');
